    #include <stdio.h>
#include <stdlib.h>

#define MAX_SIZE 100000

// Node Structure
struct Node {
    int data;
    struct Node* left;
    struct Node* right;
};

// Reverse a segment of array
void reverseArray(int* arr, int start, int end) {
    while (start < end) {
        int temp = arr[start];
        arr[start] = arr[end];
        arr[end] = temp;
        start++;
        end--;
    }
}

// Morris Postorder Traversal
int* postOrder(struct Node* root, int* size) {
    struct Node* curr = root;
    int capacity = MAX_SIZE;
    int* res = (int*)malloc(capacity * sizeof(int));
    int count = 0;

    while (curr != NULL) {

      // If right child is null,
        // put the current node data
        // in res. Move to left child.
        if (curr->right == NULL) {
            if (count >= capacity) {
                capacity *= 2;
                res = (int*)realloc(res, capacity * sizeof(int));
            }
            res[count++] = curr->data;
            curr = curr->left;
        }
        else {
            // Find the leftmost node in the right subtree
            struct Node* prev = curr->right;
            while (prev->left != NULL && prev->left != curr) {
                prev = prev->left;
            }

            // If the left child of inorder predecessor
            // already points to this node
            if (prev->left == curr) {
                prev->left = NULL;
                curr = curr->left;
            }
            else {

            // If left child doesn't point
            // to this node, then put in res
            // this node and make left
            // child point to this node
                if (count >= capacity) {
                    capacity *= 2;
                    res = (int*)realloc(res, capacity * sizeof(int));
                }
                res[count++] = curr->data;
                prev->left = curr;
                curr = curr->right;
            }
        }
    }

    // Reverse the array to get correct postorder (LRN)
    reverseArray(res, 0, count - 1);

    *size = count;
    return res;
}

// Helper to create a new node
struct Node* createNode(int data) {
    struct Node* newNode = (struct Node*)malloc(sizeof(struct Node));
    newNode->data = data;
    newNode->left = NULL;
    newNode->right = NULL;
    return newNode;
}

int main() {

    // Constructing binary tree:
    //             1
    //            / \
    //           2   3
    //          / \
    //         4  5 
    struct Node* root = createNode(1);
    root->left = createNode(2);
    root->right = createNode(3);
    root->left->left = createNode(4);
    root->left->right = createNode(5);

    int size;
    int* res = postOrder(root, &size);

    for (int i = 0; i < size; i++) {
        printf("%d ", res[i]);
    }

    free(res);
    return 0;
}


